import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Armor and Protection","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/combat/armor-and-protection.md","filePath":"en/guide/combat/armor-and-protection.md"}'),r={name:"en/guide/combat/armor-and-protection.md"};function o(s,e,l,d,c,m){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="armor-and-protection" tabindex="-1">Armor and Protection <a class="header-anchor" href="#armor-and-protection" aria-label="Permalink to &quot;Armor and Protection&quot;">​</a></h1><ul><li><strong>Design status:</strong> Accepted coverage and shared-item wear; Proposed expanded material interactions.</li><li><strong>Implementation:</strong> Stage 2A legacy armor bridge; no new layered material simulation.</li><li><strong>Availability:</strong> no new live behavior established here; current configuration not inspected.</li><li><strong>Verification:</strong> documentation reviewed 2026-10-08; no new playtest. Existing evidence is scoped in <a href="/Syrolands-Public/en/game-design/combat/status-and-open-questions.html">combat status</a>.</li></ul><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Armor protects the region actually struck; shared sleeves and leggings retain shared durability.</li><li>Material strengths, layering and maintenance are proposed extensions, not a finalized resistance chart.</li><li>Quality improves useful performance without removing equipment-loss risk.</li></ul><h2 id="protection-depends-on-where-the-hit-lands" tabindex="-1">Protection depends on where the hit lands <a class="header-anchor" href="#protection-depends-on-where-the-hit-lands" aria-label="Permalink to &quot;Protection depends on where the hit lands&quot;">​</a></h2><p>Armor covers particular body regions. Sleeves protect both arms through one shared item, and leggings protect both legs; their durability is not split into imaginary left and right items. An uncovered region does not cause the server to reroll the hit somewhere else.</p><h2 id="materials-and-condition" tabindex="-1">Materials and condition <a class="header-anchor" href="#materials-and-condition" aria-label="Permalink to &quot;Materials and condition&quot;">​</a></h2><p>The proposed direction gives plate, mail, leather and padded or layered protection different strengths and costs. Plate might stop a cut while transmitting impact. The amount, material matchups and layering rules are unresolved; this is not a current resistance chart.</p><p>Edge wear, deformation, damaged straps and seams could make maintenance tactically useful. Blacksmithing and Tailoring connect equipment knowledge to repair, while item quality describes how well an item performs and retains function. High quality does not remove the accepted risk of meaningful equipment loss.</p><p><a href="/Syrolands-Public/en/game-design/combat/armor-and-mitigation.html">Full armor specification</a> · <a href="/Syrolands-Public/en/guide/professions/blacksmithing.html">Blacksmithing</a> · <a href="/Syrolands-Public/en/guide/professions/tailoring.html">Tailoring</a> · <a href="/Syrolands-Public/en/guide/items/item-quality.html">Item Quality</a>.</p><p><a href="/Syrolands-Public/en/guide/combat/overview.html">Back to Combat overview</a></p>',11)])])}const p=t(r,[["render",o]]);export{u as __pageData,p as default};
